  if (len == 0) {
    len = strlen(line);
  }
  while (len && (line[len - 1] == '\r' || line[len - 1] == '\n')) {
    --len;
  }
  USBSerial.print(prefix);
  if (len) {
    USBSerial.write(reinterpret_cast<const uint8_t *>(line), len);
  }
  USBSerial.println();
}
